export interface PlotMasterRecord {
  plotId: string;
  farm: string;
  producer: string;
  supplier: string;
  region: string;
  hectares: number;
}

// Payload Criptografado em AES-256-CBC (Protecao total dos dados dos produtores/fazendas)
export const ENCRYPTED_PAYLOAD = {
  iv: "0865483cac0ddbe720dde15fd8bcd57f",
  data: "",
};

import crypto from "node:crypto";

const SECRET_KEY = crypto.createHash("sha256").update("FAF_EUDR_SECRET_KEY_2026_FAF").digest();
let cachedMasterList: PlotMasterRecord[] = [];

export function getMasterList(): PlotMasterRecord[] {
  if (cachedMasterList.length === 0) {
    try {
      const decipher = crypto.createDecipheriv("aes-256-cbc", SECRET_KEY, Buffer.from(ENCRYPTED_PAYLOAD.iv, "hex"));
      let decrypted = decipher.update(ENCRYPTED_PAYLOAD.data, "hex", "utf8");
      decrypted += decipher.final("utf8");
      cachedMasterList = JSON.parse(decrypted);
    } catch (err) {
      console.error("Erro ao decriptografar dados de IDPLOT:", err);
      cachedMasterList = [];
    }
  }
  return cachedMasterList;
}

export function addMasterRecord(record: PlotMasterRecord): void {
  const list = getMasterList();
  const idx = list.findIndex((p) => p.plotId.toUpperCase() === record.plotId.toUpperCase());
  if (idx >= 0) {
    list[idx] = record;
  } else {
    list.unshift(record);
  }
}

